repo='https://github.com/Stanford-TML/cloak'
def code(s): return '<div class="code"><button class="copy" aria-label="Copy command">Copy</button><pre><code>'+escape(s)+'</code></pre></div>'
def photo(n,caption): return f'<figure><a href="images/{n}" target="_blank"><img loading="lazy" src="images/{n}" alt="{escape(caption)}"></a><figcaption>{caption}</figcaption></figure>'
def section(id,title,body):return f'<section id="{id}"><h2>{title}</h2>{body}</section>'
def note(text):return '<aside class="note">'+text+'</aside>'
SAFETY_NOTICE = '<aside class="note"><strong>Safety and responsibility</strong><p>Robot assembly and operation can cause serious injury or equipment damage. These instructions, software and hardware designs are provided “as is”, without warranty. You use them at your own risk and are responsible for assessing and ensuring the safety of your installation. Follow the <a href="https://franka.de/documents">robot manufacturer’s safety instructions</a>, end-effector manuals and your institution’s safety procedures. Only trained personnel should install or operate the system. To the extent permitted by applicable law, the authors and contributors disclaim liability for injury, damage or loss arising from use of these materials.</p></aside>'

css='''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:#faf9f7;color:#26232d;font:16px/1.7 system-ui,-apple-system,sans-serif}a{color:#6544ac;text-underline-offset:3px}header{position:sticky;top:0;background:#fffefcf5;border-bottom:1px solid #e6e1dc;z-index:4;padding:16px 5%;display:flex;align-items:center;justify-content:space-between;gap:20px}header a{text-decoration:none}.brand{font-size:24px;font-weight:800;color:#8c1515}.brand small{font-size:14px;color:#777;font-weight:500;margin-left:14px}nav{display:flex;gap:18px;flex-wrap:wrap;font-size:14px}nav a[aria-current=page]{font-weight:750;color:#8c1515}.layout{max-width:1250px;margin:auto;padding:50px 28px;display:grid;grid-template-columns:215px minmax(0,1fr);gap:55px}.toc{position:sticky;top:105px;align-self:start;font-size:14px}.toc a{display:block;padding:6px 0;color:#665f70;text-decoration:none}.eyebrow{text-transform:uppercase;letter-spacing:.14em;color:#8c1515;font-size:12px;font-weight:750}h1{font-size:clamp(36px,5vw,60px);line-height:1.08;letter-spacing:-.04em;margin:12px 0 22px}h2{font-size:28px;line-height:1.25;letter-spacing:-.02em;margin:0 0 20px}h3{font-size:19px;margin:26px 0 10px}p{margin:12px 0 18px}.lead{font-size:20px;color:#665f70;max-width:760px}section{padding:36px 0;border-bottom:1px solid #e4dfe8}aside.note{padding:16px 20px;background:#f1edf7;border-left:3px solid #705197;border-radius:0 8px 8px 0;margin:22px 0;color:#44384f}figure{margin:22px 0}figure img{display:block;width:100%;max-height:560px;object-fit:contain;background:#eeeae6;border-radius:12px}figcaption{font-size:13px;line-height:1.5;color:#6e6576;margin-top:9px}.gallery{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:start}.gallery figure{margin:10px 0}.gallery img{max-height:360px}.code{position:relative;background:#25232b;color:#f4effb;border-radius:10px;margin:18px 0}pre{padding:22px;overflow:auto;font-size:13px;line-height:1.65;padding-top:40px}code{font-family:ui-monospace,SFMono-Regular,monospace}p code,li code,td code{font-size:.87em;background:#ede8f1;padding:2px 5px;border-radius:3px;overflow-wrap:anywhere}.copy{position:absolute;right:10px;top:8px;border:1px solid #635c70;background:transparent;color:#eee;border-radius:4px;padding:3px 10px;cursor:pointer}.cards{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:30px 0}.card{display:block;background:white;border:1px solid #e5dfe9;border-radius:15px;overflow:hidden;text-decoration:none;color:inherit;transition:transform .15s}.card:hover{transform:translateY(-3px);border-color:#9f86bd}.card img{width:100%;height:220px;object-fit:cover}.card>div{padding:22px}.card h2{margin:6px 0 12px}.card p{font-size:15px;color:#716777}.soon{min-height:220px;background:#ece7f3;display:grid;place-items:center;font-size:65px;color:#927dab}.step-list li{margin:10px 0}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;vertical-align:top;padding:12px;border-bottom:1px solid #e4dfe8}td{overflow-wrap:anywhere}details{margin:15px 0;background:white;border:1px solid #e5dfe9;padding:16px;border-radius:8px}summary{cursor:pointer;font-weight:650}footer{padding:35px 5%;font-size:13px;color:#777;border-top:1px solid #e5dfe9}.hero-img{width:100%;height:350px;object-fit:cover;border-radius:14px;margin:18px 0}.review{font-size:13px;color:#715d41;background:#f5eedf;padding:9px 15px;border-radius:6px}.next{display:flex;justify-content:space-between;gap:20px;padding-top:30px}@media(max-width:800px){.layout{display:block;padding:28px 20px}.toc{position:static;display:flex;gap:12px;overflow:auto;margin-bottom:25px;white-space:nowrap}.toc strong{display:none}.gallery,.cards{grid-template-columns:1fr}header{position:static;display:block;padding:15px 20px}nav{margin-top:12px;gap:14px}.brand small{margin-left:10px}.hero-img{height:260px}table{font-size:12px}th,td{padding:8px}h2{font-size:25px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.card{transition:none}}'''
css += '.brand{font-size:36px;line-height:1.2;white-space:nowrap}.cloak-name>span{display:inline-block;animation:cloak-fade 8s ease-in-out infinite}.cloak-name>span:nth-child(1){animation-delay:-3s}.cloak-name>span:nth-child(2){animation-delay:-2.4s}.cloak-name>span:nth-child(3){animation-delay:-1.8s}.cloak-name>span:nth-child(4){animation-delay:-1.2s}.cloak-name>span:nth-child(5){animation-delay:-.6s}@keyframes cloak-fade{0%,100%{opacity:1}50%{opacity:.1}}nav{gap:8px;align-items:center}nav a{color:#171717;padding:6px 9px;border-radius:6px;transition:background-color .15s,color .15s}nav a:hover{background:#eeecef;color:#000}nav a[aria-current=page]{color:#8c1515;background:#f3eaea}.home-link{display:inline-flex;align-items:center;gap:6px}.home-link svg{width:16px;height:16px}@media(prefers-reduced-motion:reduce){.cloak-name>span{animation:none}nav a{transition:none}}'
(out/'guide.css').write_text(css)
(out/'guide.js').write_text('''document.querySelectorAll('.copy').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.parentElement.querySelector('code').textContent);b.textContent='Copied';setTimeout(()=>b.textContent='Copy',1500)}catch(e){b.textContent='Select and copy'}}));''')
nav=[('index','Overview'),('robotiq','Robotiq'),('umi','UMI'),('sharpa','Sharpa'),('yam','YAM')]
steps=[('before','Before you begin'),('parts','Parts & assembly'),('desk','Franka Desk'),('software','Workstation'),('nuc','NUC controller'),('calibrate','Camera calibration'),('run','Run a policy'),('record','Videos & masks'),('troubleshoot','Troubleshooting')]
def page(slug,title,body,toc=steps):
    links=''.join(f'<a href="{s}.html"'+(' aria-current="page"' if s==slug else '')+f'>{t}</a>' for s,t in nav)
    links += '<a class="home-link" href="../index.html"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M3 11 12 3l9 8M5 10v11h5v-7h4v7h5V10"/></svg>Project page</a>'
    side=''.join(f'<a href="#{s}">{t}</a>' for s,t in toc)
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Cloak setup</title><meta name="description" content="{escape(title)}: assembly, configuration, silhouette calibration, policy deployment and mask recording."><link rel="stylesheet" href="guide.css"><script src="guide.js" defer></script></head><body><header><a class="brand" href="../index.html"><span class="cloak-name" aria-label="Cloak"><span aria-hidden="true">C</span><span aria-hidden="true">l</span><span aria-hidden="true">o</span><span aria-hidden="true">a</span><span aria-hidden="true">k</span></span><small>Setup guide</small></a><nav aria-label="Embodiments">{links}</nav></header><div class="layout"><aside class="toc"><strong>ON THIS PAGE</strong>{side}</aside><main>{body}</main></div><footer><a href="../index.html">Cloak project</a> · <a href="{repo}">Source code</a></footer></body></html>'''
    (out/f'{slug}.html').write_text(html)

data={
'robotiq':dict(title='Robotiq setup on Franka',subtitle='Configure Cloak for the standard DROID Robotiq assembly, including camera calibration and policy deployment.',hero='view7570.jpg',parts='Robotiq 2F-85, its DROID coupling and power/data hardware; ZED Mini wrist camera; the printed camera mount and its fasteners; the existing external ZED camera.',assembly='''<ol class="step-list"><li>If your working DROID Robotiq assembly matches these photos, <strong>leave it mounted</strong>. Cloak uses the standard DROID Robotiq orientation.</li><li>If rebuilding after another embodiment, stop the controller and follow the normal DROID powered-down hardware-change procedure. Begin at the bare flange, attach the camera mount in the orientation shown, seat the ZED Mini, then attach the Robotiq coupling and gripper.</li><li>Reconnect the camera USB cable and the DROID Robotiq power/data connections. Check connector seating, retention and slack before moving.</li></ol>''',pics=[('view7556.jpg','ZED Mini, camera mount parts 1 and 2, and USB cable.'),('view7557.jpg','Robotiq coupling, gripper and power/data components.'),('view7565.jpg','Robotiq mount orientation and exposed screws.'),('view7566.jpg','Camera seated with USB connection visible.'),('view7568.jpg','Coupling attachment before fitting the gripper.'),('view7569.jpg','Completed Robotiq assembly.')],desk='''<p>Select <strong>Other</strong>, upload <a href="configs/robotiq_2f85.json" download>robotiq_2f85.json</a>, then press <strong>Apply</strong>. Confirm the values-differ warnings disappear. Use this file only for the matching assembly pictured here.</p>''',quality='0.715 → 0.805',overlay='robotiq-calibration.png'),
'umi':dict(title='UMI setup on Franka',subtitle='Use the native Franka Hand with UMI fingertips and a camera mount installed in the UMI orientation.',hero='view7575.jpg',parts='Native Franka Hand, UMI fingertips and their mounting hardware; the same ZED Mini and printed camera mount used for Robotiq; native hand-to-arm cable; the existing external ZED camera.',assembly='''<ol class="step-list"><li>Quit the client and stop the controller. Follow the normal powered-down hardware-change procedure, then remove the previous end effector and camera mount to expose the flange.</li><li>Install the camera mount in the <strong>UMI orientation shown below</strong>. The part is the same as Robotiq, but its orientation is different.</li><li>Fit the native Franka Hand and UMI fingertips using their matching hardware. Connect the hand to the arm wrist connector as shown.</li><li>Seat the ZED Mini, connect USB and secure cables with enough slack for wrist motion. Do not reuse the Robotiq calibration after rotating the camera mount.</li></ol>''',pics=[('view7556.jpg','The same camera and printed mount used for Robotiq.'),('view7571.jpg','Native hand, UMI fingertips and mounting interface.'),('view7572.jpg','UMI-specific camera-mount orientation before the hand is installed.'),('view7574.jpg','Hand attachment and fingertip fasteners.'),('view7576.jpg','Native hand cable connected to the wrist connector.')],desk='''<p>Select <strong>Franka Hand</strong> instead of Other, and apply the selection. This setup uses the native internal configuration. <strong>No custom mechanical-data JSON upload is required.</strong></p><p>Home the hand after changing fingertips, with empty fingers and their travel clear. Do not use the historical <code>umi_roll135.json</code> file for this procedure.</p>''',quality='0.554 → 0.582',overlay='umi-calibration.png'),
'sharpa':dict(title='Sharpa setup on Franka',subtitle='Install the right Sharpa hand on the angled adapter, with the dedicated extended camera bracket.',hero='view7586.jpg',parts='Right Sharpa hand, angled adapter and matched fasteners; dedicated Sharpa camera bracket and retainer; ZED Mini and USB cable; Sharpa power supply, interface and data cable; existing external ZED camera.',assembly='''<ol class="step-list"><li>Quit the client and stop the controller. Follow the normal powered-down hardware-change procedure and remove the previous end effector and camera mount.</li><li>Install the dedicated Sharpa camera bracket. It uses the <strong>same robot-side holes as the Robotiq mount</strong>, but is a different printed part. Use the photos for bracket orientation and camera seating.</li><li>Install the angled adapter and right hand in the illustrated orientation. The hand extends sideways relative to the flange. Do not substitute the straight adapter or a left hand.</li><li>Connect the hand to its power/data interface and workstation, and the camera by USB. Secure loose cable loops while allowing wrist rotation. Keep cables out of the finger travel.</li></ol>''',pics=[('view7577.jpg','Camera mount parts 1 and 2, and ZED Mini.'),('view7579.jpg','Right hand, angled adapter, fasteners and power/data components.'),('view7581.jpg','Camera bracket uses the Robotiq robot-side holes; camera seating shown.'),('view7583.jpg','Angled adapter and hand attachment.'),('view7586.jpg','Completed assembly. Secure cable loops with sufficient wrist slack.')],desk='''<p>Select <strong>Other</strong>, upload <a href="configs/sharpa_angled.json" download>sharpa_angled.json</a>, and press <strong>Apply</strong>. Verify the configuration matches the pictured angled right-hand assembly. The identity flange-to-end-effector transform is intentional in this supplied configuration.</p>''',quality='0.585 → 0.801',overlay='sharpa-calibration.png')}

for slug,d in data.items():
 b=f'<p class="eyebrow">Hardware guide / {slug}</p><h1>{d["title"]}</h1><p class="lead">{d["subtitle"]}</p><img class="hero-img" src="images/{d["hero"]}" alt="Completed {d["title"]} assembly">'
 b+=SAFETY_NOTICE
 b+=section('before','01 / Start from working DROID','''<p>Your DROID installation must already work: Franka arm, real-time NUC, workstation, wrist and external ZED cameras, networking and robot control. This guide covers the conversion to Cloak, not initial DROID installation. Refer to the <a href="https://droid-dataset.github.io/droid/">DROID documentation</a> for that baseline.</p>''')
 if slug=='robotiq':b+='<p>The full assembly process is shown below for completeness. If your DROID system is fully installed and working with the Robotiq gripper, camera and Franka Desk configuration, skip to <a href="#software">step 04: Workstation and checkpoint</a>.</p>'
 b+=section('parts','02 / Parts and mounting',f'<p>{d["parts"]}</p>'+downloads(slug)+d['assembly']+'<div class="gallery">'+''.join(photo(n,c) for n,c in d['pics'])+'</div>')
 b+=section('desk','03 / Configure Franka Desk',desk_steps(slug))
 install='''<p>On the GPU workstation, use the Cloak checkout that contains these setup scripts.</p>'''+code('git clone https://github.com/Stanford-TML/cloak.git\ncd cloak\nuv sync --group client --group dev\n# Create settings only when they do not already exist.\n[ -f .env ] || cp .env.example .env')+'<p></p>'
 env=f'''EMBODIMENT={slug}
CLOAK_NUC_IP=<your-nuc-ip>
WRIST_CAMERA_ID=<wrist-zed-serial>
EXTERNAL_CAMERA_ID=<external-zed-serial>
WRIST_CAM_LENS=left
POLICY_HOST=127.0.0.1
POLICY_PORT=8000
CONFIG=pi05_full_droid_finetune_v3-1_ik
CHECKPOINT_DIR=/absolute/path/to/cloak_VLA/100000
DEBUG_MASKS=true'''
 install+=camera_setup(code)+'<h3>Configure the workstation</h3><p>Enter your addresses and camera serial numbers in <code>.env</code>:</p>'
 install+=code(env)+'<p>Replace every angle-bracket placeholder before running. Enter camera serial numbers without the <code>SN</code> prefix. Use <code>127.0.0.1</code> only when the policy server runs on the same workstation as the client.</p><p>Download <strong>Cloak-VLA</strong> from the <a href="https://drive.google.com/drive/folders/1DWXAGzNjsc-iyNWnbEMEgyhw4JkP-a7f?usp=drive_link">checkpoint folder</a>. Reuse an existing download. Point at the checkpoint directory containing <code>params/</code> and <code>assets/</code>, not the ZIP file. This guide does not require training.</p>'
 if slug=='sharpa':install+='<h3>Sharpa SDK and network</h3><p>Obtain the vendor SDK and place <code>SharpaWaveSDK_4.3.4/</code> at the repository root. Its Python extension must match the workstation Python version. Connect the right hand to the workstation network used by the SDK. The NUC runs the arm only; the workstation SDK controls the hand.</p><p>The current policy uses camera and joint feedback. Tactile reception is not required by it and is not covered by this guide. A tactile bind-address warning must be resolved separately if you need tactile data.</p>'
 b+=section('software','04 / Workstation and checkpoint',install)
 nuc='''<p>Keep the existing working DROID container available for rollback. Copy <code>deployment/nuc/</code> into a separate directory on the NUC. Review <code>deployment/nuc/backend-manifest.json</code> in the same checkout and the robot configuration for your arm and libfranka version before starting a replacement.</p>'''+'<p>Build against an existing verified DROID image compatible with your arm and libfranka version. The historical registry tag is not publicly retrievable in our check; use your working DROID image and verify the dependencies in <a href="https://github.com/Stanford-TML/cloak/blob/main/deployment/nuc/README.md">the NUC package reference</a>. A fresh base-image build has not been validated.</p>'+code('''# On the NUC, in the copied deployment/nuc directory:
docker build --build-arg BASE_IMAGE=<verified-droid-base> -t cloak-nuc:local .
export CLOAK_NUC_IMAGE=cloak-nuc:local
export ROBOT_IP=<arm-controller-ip>
docker compose config
# Quit any robot client, then stop the existing controller container first.
docker stop <existing-controller-container>
docker compose up -d
docker compose logs -f''')+f'<p>The bridge listens on port <code>4242</code>; controller processes start when the workstation requests them. For {d["title"]}, '+{'robotiq':'the bridge selects the Robotiq driver. Confirm the configured USB/RS-485 device matches your DROID wiring.','umi':'the bridge selects the native Franka Hand driver and waits for valid hand metadata.','sharpa':'the bridge starts the arm without a parallel-gripper driver; the workstation SDK connects to the right Sharpa hand.'}[slug]+'</p><p>Never run both controller containers against the robot at once. To roll back, quit the client, stop the Cloak service with <code>docker compose stop</code>, then restart the preserved original container. The workstation environment is not installed inside the NUC container.</p>'
 if slug=='robotiq':
  nuc=nuc.replace('docker compose config', '# Set the verified Robotiq USB/RS-485 device on the NUC.\nexport ROBOTIQ_PORT=/dev/ttyUSB0\ndocker compose config')
  nuc+='<p>Replace <code>/dev/ttyUSB0</code> above with the verified Robotiq serial device on your NUC. UMI and Sharpa do not use this driver.</p>'
 b+=section('nuc','05 / Start the NUC bridge',nuc)
 cal='<p>Silhouette Calibration estimates the wrist camera extrinsics from images captured while the arm moves through several poses. Clear the workspace before starting:</p>'+code(f'bash scripts/calibrate_wrist_camera.sh --embodiment {slug}')+f'<p>The outputs are a calibration file, <code>deployment/calibration/calibration_info_{slug}.json</code>, and a mask visualization, <code>scratch/wrist_calibration/{slug}/mask_overlay_{slug}.png</code>. Deployment loads the calibration automatically. Inspect the overlay to confirm that the silhouette aligns with the end effector.</p>'+photo(d['overlay'],f'{slug.title()} silhouette calibration: observed mask, fitted overlay, and camera pose.')+'<p>To fit an existing capture without moving the robot:</p>'+code(f'bash scripts/calibrate_wrist_camera.sh --embodiment {slug} --captures scratch/wrist_calibration/{slug}')+'<p>Recalibrate after changing the camera mount or orientation.</p>'
 b+=section('calibrate','06 / Calibrate the wrist camera',cal)
 run='<p>Start the policy server on the GPU workstation:</p>'+code(f'bash scripts/serve_policy.sh --embodiment {slug}')+'<p>Once the server is ready, start the robot client in another terminal:</p>'+code(f'bash scripts/deploy_policy.sh --embodiment {slug}')+'<p>Keep the arm’s home path clear during startup and reset. Check end-effector connectivity before entering a task instruction, then supervise the rollout. The client provides controls for stopping and saving the episode.</p>'
 b+=section('run','07 / Run a policy',run)
 b+=section('record','08 / Save and inspect the output','''<p>With <code>DEBUG_MASKS=true</code> set before starting the server, answer <code>y</code> to “Save video?” and enter a descriptive label. Outputs appear in <code>test_videos/</code>:</p><table><thead><tr><th>File</th><th>Contents</th></tr></thead><tbody><tr><td><code>&lt;episode&gt;.mp4</code></td><td>External and wrist RGB views.</td></tr><tr><td><code>&lt;episode&gt;_mask.mp4</code></td><td>Four panels: external RGB, wrist RGB, inference wrist image with green mask, binary mask.</td></tr><tr><td><code>&lt;episode&gt;_masks.npz</code></td><td>Boolean masks, paired wrist images, control-step indices and nominal FPS.</td></tr></tbody></table>'''+photo(f'{slug}-mask-rollout.jpg',f'{d["title"]}: frame from the recorded hardware rollout, showing external RGB, wrist RGB, mask overlay and binary mask.')+'''<p>Masks update at policy queries. Between queries, the lower panels hold the matching inference image and mask, so they can lag the current camera views above. These are source pixel masks, not the model's final token grid. Playback uses nominal 15 Hz; inference pauses are not encoded as wall-clock timing.</p><p>If no mask files appear, check that the server was restarted after enabling <code>DEBUG_MASKS</code>. The client’s <code>--debug</code> option uses mock hardware and is not the mask-recording switch.</p>''')
 trouble='''<details><summary>Controller timeout, reflex stop or communication fault</summary><p>Stop the run and inspect the NUC logs before retrying. Check that only one bridge is running, that the robot is ready for external control, and that the real-time network/backend is compatible. Do not treat automatic error recovery as proof that the underlying fault is resolved.</p></details><details><summary>Mask does not follow the hand</summary><p>Check embodiment, camera serial, lens and mount orientation. Rerun silhouette calibration after any mounting change. Inspect several poses before trusting the result.</p></details><details><summary>Hand feedback or grasping is wrong</summary><p>At the deployment instruction prompt, with the empty hand clear, type <code>g</code> and press Enter to check hand connectivity and motion. It commands the hand to close and reopen. Confirm both movements before entering a task. If it does not respond, check power, connectors and the hand driver. HAND_SPECIFIC_TROUBLE</p></details>'''
 trouble=trouble.replace('HAND_SPECIFIC_TROUBLE', {'robotiq':'Confirm Robotiq activation, power and USB/RS-485 device selection on the NUC. Check measured opening as well as physical finger motion.','umi':'Confirm native Franka Hand selection and homing, valid maximum-width metadata, and settled open/close/reopen feedback. Rerun the empty-hand check before attempting an object grasp.','sharpa':'Confirm the right-hand SDK connection on the workstation and restart the policy server with scripts/serve_policy.sh so fixed-hand IK is enabled. All fingers, including the pinky, should follow the same hand interpolation as g.'}[slug])
 b+=section('troubleshoot','09 / Troubleshooting',trouble)
 b+='<div class="next"><a href="index.html">Setup guide</a><a href="../index.html">Back to Cloak</a></div>'
 page(slug,d['title'],b)

